tool_input.new_string:
// 区域查询参数：未选中区域（全市）时不携带 regionCode 字段，避免发出 ?regionCode= 空参
export function getRegionParams(activeRegion) {
  const regionCode = getRegionCodeByIndex(activeRegion)
  return regionCode ? { regionCode } : {}
}

// 子区域码到其所属 Tree 区域名称的映射：高新区/科创新城 在部门树中无独立节点，
// 穿透后左树应选中其所在的上级行政区节点（高新区归榆阳区、科创新城归横山区）。
const SUB_REGION_TREE_NAME_MAP = {
  610893: '榆阳区',
  610894: '横山区'
}

// 由行政区划码得到部门树中对应节点的区域名称（用于大屏穿透后左树自动选中）。
// 子区域映射到其所属上级行政区；未匹配返回空字符串（保持全市/根节点默认）。
export function getTreeRegionNameByCode(regionCode) {
  if (!regionCode) return ''
  const code = String(regionCode)
  if (SUB_REGION_TREE_NAME_MAP[code]) return SUB_REGION_TREE_NAME_MAP[code]
  return REGION_CODE_NAME_MAP[code] || ''
}

initialSelectedId: {
  type: [String, Number],
  default: null
},
// 大屏穿透场景：按区域名称匹配部门树节点并默认选中（无 initialSelectedId 时生效）
initialRegionName: {
  type: String,
  default: ''
},

initDefaultSelection() {
  const root = this.treeData[0]
  if (!root) return
  // 优先级：显式 initialSelectedId > 大屏穿透传入的区域名称 > 根节点
  let targetNode = null
  if (this.initialSelectedId != null) {
    targetNode = this.findNodeById(this.treeData, this.initialSelectedId)
  }
  if (!targetNode && this.initialRegionName) {
    targetNode = this.findNodeByRegionName(this.treeData, this.initialRegionName)
  }
  if (!targetNode) targetNode = root
  this.selectNode(targetNode, { emit: false })
  this.$emit('tree-ready', targetNode)
},
// 按区域名称在树中查找节点（节点名称取 deptName/name/label，去掉后缀「区/县/市」再比一次兜底）
findNodeByRegionName(nodes, regionName) {
  if (!regionName || !nodes?.length) return null
  const target = String(regionName).trim()
  const stripSuffix = (name) => String(name || '').trim().replace(/[区县市]$/, '')
  const targetBase = stripSuffix(target)
  for (const node of nodes) {
    const nodeName = node.deptName || node.name || node.label || ''
    if (String(nodeName).trim() === target) return node
    if (targetBase && stripSuffix(nodeName) === targetBase) return node
    const found = this.findNodeByRegionName(node.children, regionName)
    if (found) return found
  }
  return null
},

resolvedInitialSelectedId() {
  if (this.pendingTreeDefaultReset) return null
  return this.cachedParentDeptId
},
// 大屏穿透：携带 region(行政区划码) 跳转时，左树应自动选中对应区域节点（bug 6213）
// 仅在「非平铺、非重置、无缓存 parentDeptId」时按区域名称匹配，避免覆盖常规进入的选中态
resolvedInitialRegionName() {
  if (this.pendingTreeDefaultReset || this.flat) return ''
  if (this.cachedParentDeptId != null) return ''
  const query = this.$route.query || {}
  if (query.from !== 'screen' || !query.region) return ''
  return getTreeRegionNameByCode(query.region)
}

