function redisCmd(args){
  return new Promise((resolve,reject)=>{
    const sock=net.createConnection({host:'172.10.0.2',port:6379});
    let buf=Buffer.alloc(0); let step=0;
    const send=(parts)=>{
      let s='*'+parts.length+'\r\n';
      for(const p of parts){ const b=Buffer.from(String(p)); s+='$'+b.length+'\r\n'+p+'\r\n'; }
      sock.write(s);
    };
    sock.on('connect',()=>send(['AUTH','Redis_gqpVKeIEUGia1tQe']));
    sock.on('data',(d)=>{
      buf=Buffer.concat([buf,d]);
      // crude: when we have full response
      const txt=buf.toString('utf8');
      if(step===0 && txt.includes('\r\n')){ // auth reply
        step=1; buf=Buffer.alloc(0); send(args); return;
      }
      if(step===1 && /\r\n$/.test(txt) && (txt.startsWith('$')||txt.startsWith('+')||txt.startsWith('-')||txt.startsWith(':'))){
        sock.end(); resolve(txt);
      }
    });
    sock.on('error',reject);
    setTimeout(()=>{ try{sock.end()}catch(e){}; resolve('TIMEOUT:'+buf.toString('utf8')); },5000);
  });
}

